<script>import {adminApi} from "../../services/adminApi";export default{data(){return{loading:true,d:{}}},async mounted(){try{this.d=await adminApi.get("dashboard")}finally{this.loading=false}},methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}}}</script><template><div><div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="mb-1">Visão Geral do SaaS</h4><p class="text-muted mb-0">Indicadores reais da operação Seven Shows.</p></div></div><div v-if="loading" class="text-center py-5"><div class="spinner-border text-primary"></div></div><div v-else class="row"><div v-for="c in [{l:'Músicos / Tenants',v:d.tenants,i:'ri-user-star-line'},{l:'Contratantes',v:d.contractors,i:'ri-group-line'},{l:'Assinaturas ativas',v:d.activeSubscriptions,i:'ri-checkbox-circle-line'},{l:'Shows',v:d.shows,i:'ri-calendar-event-line'}]" :key="c.l" class="col-xl-3 col-md-6"><div class="card card-animate"><div class="card-body"><div class="d-flex"><div class="flex-grow-1"><p class="text-uppercase fw-medium text-muted mb-0">{{c.l}}</p><h3 class="mt-3 mb-0">{{c.v||0}}</h3></div><div class="avatar-sm"><span class="avatar-title bg-primary-subtle text-primary rounded fs-3"><i :class="c.i"></i></span></div></div></div></div></div></div><div v-if="!loading" class="row"><div v-for="c in [{l:'GMV de shows',v:money(d.gmv)},{l:'Receita marketplace',v:money(d.marketplaceRevenue)},{l:'Receita SaaS recebida',v:money(d.saasRevenue)},{l:'Receita total',v:money(d.totalRevenue)}]" :key="c.l" class="col-xl-3 col-md-6"><div class="card"><div class="card-body"><p class="text-muted mb-1">{{c.l}}</p><h4 class="mb-0">{{c.v}}</h4></div></div></div></div><div v-if="!loading && d.overdueSubscriptions" class="alert alert-warning"><i class="ri-error-warning-line me-2"></i><strong>{{d.overdueSubscriptions}}</strong> assinatura(s) vencida(s) requerem atenção.</div></div></template>